<script setup lang="ts">
const name = ref('Plantilla principal'); const html = ref(''); const fileName = ref(''); const saved = ref<any[]>([]); const message = ref(''); const error = ref('')
const markers = ['{{TITULO_A}}', '{{TITULO_B}}', '{{VALIDACION}}', '{{BENEFICIOS}}', '{{PROMOCION}}', '{{CTA}}', '{{PRODUCTO}}', '{{PAIS}}']
async function load() { saved.value = await $fetch<any[]>('/api/templates'); if (saved.value[0] && !html.value) { name.value = saved.value[0].name; html.value = saved.value[0].html } }; onMounted(load)
function readFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; fileName.value = file.name; const reader = new FileReader(); reader.onload = () => { html.value = String(reader.result || '') }; reader.readAsText(file) }
async function save() { try { await $fetch('/api/templates', { method: 'POST', body: { name: name.value, html: html.value } }); message.value = 'Plantilla guardada y activada.'; await load() } catch (e: any) { error.value = e?.data?.statusMessage || 'No se pudo guardar la plantilla.' } }
</script>
<template><div class="mx-auto max-w-7xl px-5 py-10 lg:px-8"><div class="mb-8"><NuxtLink to="/admin" class="text-sm font-semibold text-brand">← Administración</NuxtLink><h1 class="mt-3 text-4xl font-bold">Plantillas visuales</h1><p class="mt-3 max-w-2xl text-slate-500">Carga el HTML maestro que se utilizará para renderizar las imágenes A, B y C.</p></div><div v-if="message" class="mb-4 rounded-xl bg-emerald-50 p-4 text-sm text-emerald-700">{{ message }}</div><div v-if="error" class="mb-4 rounded-xl bg-rose-50 p-4 text-sm text-rose-700">{{ error }}</div><div class="grid gap-6 lg:grid-cols-[1fr_360px]"><section class="card p-6"><div class="flex flex-wrap gap-3"><input v-model="name" class="input flex-1" placeholder="Nombre de la plantilla"><label class="btn-secondary cursor-pointer">Subir HTML<input type="file" accept=".html,.htm,.txt" class="hidden" @change="readFile"></label><span v-if="fileName" class="self-center text-xs text-slate-400">{{ fileName }}</span></div><textarea v-model="html" class="input mt-4 min-h-[520px] font-mono text-xs" placeholder="Pega aquí el HTML de tu creativo..."></textarea><div class="mt-4 flex items-center justify-between gap-3"><p class="text-xs text-slate-500">La plantilla activa se usa en el generador.</p><button class="btn-primary" @click="save">Guardar y activar</button></div></section><aside class="space-y-5"><div class="card p-5"><p class="eyebrow">Marcadores disponibles</p><div class="mt-4 flex flex-wrap gap-2"><code v-for="marker in markers" :key="marker" class="rounded-lg bg-slate-100 px-2 py-1 text-xs dark:bg-slate-800">{{ marker }}</code></div><p class="mt-4 text-sm text-slate-500"><code>&#123;&#123;BENEFICIOS&#125;&#125;</code> se convierte automáticamente en elementos <code>&lt;li&gt;</code> con check.</p></div><div class="card p-5"><p class="eyebrow">Plantillas guardadas</p><div class="mt-3 space-y-2"><div v-for="item in saved" :key="item._id" class="rounded-lg bg-slate-50 p-3 text-sm dark:bg-slate-800"><b>{{ item.name }}</b><span class="ml-2 text-xs text-mint">Activa</span><p class="mt-1 text-xs text-slate-400">{{ new Date(item.updatedAt).toLocaleString() }}</p></div><p v-if="!saved.length" class="text-sm text-slate-400">Todavía no hay plantillas.</p></div></div></aside></div></div></template>
